// Shared helpers for the PDF build scripts.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
export const DOCS = path.join(ROOT, 'docs');

// Mandatory footer text for every generated PDF (exact wording, Cotiviti document-footer policy).
export const FOOTER_LINES = [
  'Generated by AI. AI can make mistakes. Validate before relying upon this document.',
  '© 2026 Cotiviti, Inc. All rights reserved. All proprietary information shall remain the sole and exclusive property of Cotiviti, Inc.',
];

export function read(rel) {
  const file = path.isAbsolute(rel) ? rel : path.join(ROOT, rel);
  return fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
}

export function exists(rel) {
  return fs.existsSync(path.isAbsolute(rel) ? rel : path.join(ROOT, rel));
}

/** Shifts markdown heading levels (never beyond h6) while ignoring fenced code. */
export function shiftHeadings(md, by) {
  let fence = false;
  return md
    .split('\n')
    .map((line) => {
      if (/^```/.test(line)) fence = !fence;
      if (fence) return line;
      const m = /^(#{1,6})\s+(.*)$/.exec(line);
      if (!m) return line;
      return `${'#'.repeat(Math.min(6, m[1].length + by))} ${m[2]}`;
    })
    .join('\n');
}

/** Removes the first H1 line (the chapter title is supplied separately). */
export function dropTitle(md) {
  return md.replace(/^#\s+.*\n+/, '');
}

/** Turns local markdown links into plain text (a PDF has no sibling files). */
export function stripLocalLinks(md) {
  return md.replace(/\[([^\]]+)\]\((?!https?:|#)[^)]*\)/g, '$1');
}

/** Markdown image for a rendered diagram: stem is the .mmd file name without extension, e.g. '05-order-state-machine'. */
export function diagram(stem, caption, baseDir = DOCS) {
  const png = path.join(DOCS, 'diagrams', 'rendered', `${stem}.png`);
  if (!fs.existsSync(png)) return `\n_(diagram ${stem} not available)_\n`;
  return `\n![${caption}](${path.relative(baseDir, png).replace(/\\/g, '/')})\n`;
}

/** Concatenate markdown parts, each separated by a blank line. */
export function join(...parts) {
  return parts.filter(Boolean).join('\n\n');
}

/** Heading demotion that keeps a document's own H1 as an H2 inside a chapter. */
export function sub(rel, by = 1) {
  return shiftHeadings(stripLocalLinks(read(rel)), by);
}
